.gzp-desk{
          bakgrund:
            radiell gradient (120 % 70 % vid 50 % 0 %, rgba(214,178,110,.05), transparent 58%),
            radiell gradient (130 % 100 % vid 50 % 108 %, rgba(0,0,0,.34), transparent 62 %),
            /* träfibrer — brett och oregelbundet fördelade (gamla hårfästen
               Det såg ut som sammet) */
            repeating-linear-gradient(92deg,
              rgba(0,0,0,.13) 0 3px,
              transparent 3px 17px,
              rgba(255,255,255,.016) 17px 20px,
              transparent 20px 41px,
              rgba(0,0,0,.09) 41px 43px,
              transparent 43px 74px),
            /* skarvar på brädorna */
            repeating-linear-gradient(90deg,
              rgba(0,0,0,.42) 0 2px,
              transparent 2px 148px),
            linjär-gradient(180deg, #33261a 0%, #291e13 52%, #1c150d 100%);
        }
        .gzp-under{
          position: absolut;
          infälld: 0;
          bakgrund: linjär-gradient(180deg, #e6d9b6 0%, #d6c599 100%);
          box-shadow: 0 12px 22px rgba(0,0,0,.45), infälld 0 0 0 1px rgba(120,90,36,.2);
          transform: rotate(-1,15deg) translateY(5px);
        }
        .gzp-under--2{
          bakgrund: linjär-gradient(180deg, #e1d2ab 0%, #cfbd90 100%);
          transform: rotate(.85deg) translateY(9px);
        }
